/**
 * Phase v2-06 — pure YouTube link model.
 *
 * Video links stay **single-source** in `links.video` by owner decision
 * (`69834c7`, `docs/DECISIONS.md`): this module only *reads* them. Nothing here
 * rewrites a URL, re-hosts a video, fetches a player script, or calls oEmbed at
 * runtime. `data/media/<videoId>.json` is generated by `tools/fetch-media.mjs`
 * (build time, then committed) and imported with the rest of the content bundle,
 * which is why the theatre works offline and never touches the network to draw
 * a title.
 *
 * The IFrame player parameters are the official documented ones
 * (https://developers.google.com/youtube/iframe_api_reference):
 *   enablejsapi=1, origin, rel=0, iv_load_policy=3, playsinline=1,
 *   cc_load_policy=1, host=https://www.youtube-nocookie.com, start=<s>.
 * We never modify, overlay or block the player (ToS §4.13).
 */

export const YOUTUBE_EMBED_HOST = 'https://www.youtube-nocookie.com'
export const YOUTUBE_IFRAME_API = 'https://www.youtube.com/iframe_api'
/** Deep links (`?t=`) may point up to 24 h into a video. */
export const MAX_START_SECONDS = 86_400

const VIDEO_ID = /^[A-Za-z0-9_-]{11}$/
const YOUTUBE_HOSTS = new Set(['youtu.be', 'www.youtube.com', 'youtube.com', 'm.youtube.com', 'music.youtube.com'])

/** The eleven-character id, or null when the link is not a watchable video. */
export function parseVideoId(url: string | undefined | null): string | null {
  if (!url) return null
  let parsed: URL
  try {
    parsed = new URL(url)
  } catch {
    return null
  }
  const host = parsed.hostname.toLowerCase()
  if (!YOUTUBE_HOSTS.has(host) && host !== 'youtube-nocookie.com' && host !== 'www.youtube-nocookie.com') {
    return null
  }
  const candidate = host === 'youtu.be'
    ? parsed.pathname.replace(/^\/+/, '').split('/')[0]
    : parsed.searchParams.get('v') ?? parsed.pathname.match(/^\/(?:embed|shorts|live)\/([^/?#]+)/)?.[1] ?? ''
  return VIDEO_ID.test(candidate) ? candidate : null
}

export function watchUrl(videoId: string): string {
  return `https://www.youtube.com/watch?v=${videoId}`
}

/** `754` → `12:34`; an hour and over reads `1:02:03`. Never negative. */
export function formatClock(seconds: number): string {
  const total = Number.isFinite(seconds) && seconds > 0 ? Math.floor(seconds) : 0
  const hours = Math.floor(total / 3600)
  const minutes = Math.floor((total % 3600) / 60)
  const rest = total % 60
  const mm = hours > 0 ? String(minutes).padStart(2, '0') : String(minutes)
  return `${hours > 0 ? `${hours}:` : ''}${mm}:${String(rest).padStart(2, '0')}`
}

/** A `?t=` value: digits only, ≤ 24 h. Anything else means "start at 0". */
export function parseStart(value: string | undefined | null): number {
  if (!value) return 0
  const digits = value.trim().replace(/s$/, '')
  if (!/^\d{1,5}$/.test(digits)) return 0
  return Math.min(Number(digits), MAX_START_SECONDS)
}

/**
 * The embed URL for one player instance. `origin` is required by the IFrame API
 * so `postMessage` events are attributed to us; on a static `file://` build
 * (never shipped) it degrades to the documented default.
 */
export function embedUrl(videoId: string, options: { origin?: string; start?: number } = {}): string {
  const params = new URLSearchParams({
    enablejsapi: '1',
    rel: '0',
    iv_load_policy: '3',
    playsinline: '1',
    cc_load_policy: '1',
    host: YOUTUBE_EMBED_HOST,
    ...(options.origin ? { origin: options.origin } : {}),
  })
  if (options.start && options.start > 0) params.set('start', String(Math.floor(options.start)))
  return `${YOUTUBE_EMBED_HOST}/embed/${videoId}?${params.toString()}`
}

/* --- player state ---------------------------------------------------------- */

/** The five documented `onStateChange` values; `getPlayerState()` adds -1/5. */
export type PlayerState = 'unstarted' | 'ended' | 'playing' | 'paused' | 'buffering' | 'cued' | 'unknown'

const PLAYER_STATES: Record<number, PlayerState> = {
  [-1]: 'unstarted',
  0: 'ended',
  1: 'playing',
  2: 'paused',
  3: 'buffering',
  5: 'cued',
}

export function playerState(code: number | null | undefined): PlayerState {
  if (typeof code !== 'number') return 'unknown'
  return PLAYER_STATES[code] ?? 'unknown'
}

/**
 * The documented error codes. `2/5/100/101/150` mean the video cannot be
 * embedded (removed, private, or embedding disabled) — those become the
 * dead-link card with an `Open on YouTube` fallback, never a blank frame.
 */
export const EMBED_FAILURES = new Set([2, 5, 100, 101, 150])

export function embedFailureMessage(code: number | null | undefined): string {
  if (code === 2) return 'That video id is not valid any more.'
  if (code === 5) return 'This video cannot play in an embedded player.'
  if (code === 100) return 'The video is private, removed, or not public.'
  if (code === 101 || code === 150) return 'The owner does not allow this video to be embedded.'
  return `The player reported error ${code ?? '?'}.`
}

/** Errors that are worth writing to `data/media` as a dead link. */
export function isDeadLinkError(code: number | null | undefined): boolean {
  return typeof code === 'number' && (EMBED_FAILURES.has(code) || code === 0)
}

/**
 * 60% of the runtime counts as "watched". This is a soft, local notion of
 * watched — one `localStorage` flag, never a Firestore write and never a score.
 */
export const WATCHED_RATIO = 0.6

export function watchedPercent(current: number, duration: number): number {
  if (!Number.isFinite(current) || !Number.isFinite(duration) || duration <= 0) return 0
  const ratio = Math.max(0, Math.min(1, current / duration))
  return Math.round(ratio * 100)
}

export function isWatched(current: number, duration: number): boolean {
  return Number.isFinite(duration) && duration > 0 && current / duration >= WATCHED_RATIO
}

export type WatchFlag = {
  at: string
  /** Peak share of the video seen, 0–100. */
  percent: number
}

/** `dsa-archive.watch.v1` — the only thing the theatre stores locally. */
export const WATCH_STORAGE_KEY = 'dsa-archive.watch.v1'
export const WATCH_FLAG_LIMIT = 400

export type WatchFlags = Record<string, WatchFlag>

/**
 * A viewed flag keeps its highest percentage, so re-watching a video from the
 * start never erases the fact that it was watched once.
 */
export function mergeWatchFlag(flags: WatchFlags, videoId: string, percent: number, now = new Date()): WatchFlags {
  if (!VIDEO_ID.test(videoId)) return flags
  const previous = flags[videoId]
  const next: WatchFlag = {
    at: now.toISOString(),
    percent: Math.max(Math.round(Math.max(0, Math.min(100, percent))), previous?.percent ?? 0),
  }
  const merged: WatchFlags = { ...flags, [videoId]: next }
  const ids = Object.keys(merged)
  if (ids.length <= WATCH_FLAG_LIMIT) return merged
  // Oldest first out; the cap keeps the flag store well inside one localStorage slot.
  ids.sort((a, b) => merged[a].at.localeCompare(merged[b].at))
  for (const id of ids.slice(0, ids.length - WATCH_FLAG_LIMIT)) delete merged[id]
  return merged
}

export function sanitizeWatchFlags(raw: unknown): WatchFlags {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return {}
  const out: WatchFlags = {}
  for (const [videoId, value] of Object.entries(raw as Record<string, unknown>)) {
    if (!VIDEO_ID.test(videoId)) continue
    if (typeof value !== 'object' || value === null) continue
    const flag = value as Record<string, unknown>
    const percent = typeof flag.percent === 'number' && Number.isFinite(flag.percent) ? flag.percent : 0
    out[videoId] = {
      at: typeof flag.at === 'string' ? flag.at.slice(0, 40) : '',
      percent: Math.max(0, Math.min(100, Math.round(percent))),
    }
  }
  return out
}
